<?php

function check($n) {
    $s = 0;
    while ($n > 0) {
        $s += $n % 10;
        $n = (int)($n / 10);
    }
    return $s == 10;
}

function solution($reader, $writer) {
    $k = intval(trim(fgets($reader)));
    for ($i = 19; $k > 0; $i++) {
        if (check($i)) {
            $k--;
        }
        if ($k == 0) {
            fwrite($writer, $i . "\n");
            return;
        }
    }
}

$stdin = fopen('php://stdin', 'r');
$stdout = fopen('php://stdout', 'w');

solution($stdin, $stdout);

fclose($stdin);
fclose($stdout);
?>
